291	    if (!match) continue;
292	    const file = path.join(dir, name);
293	    try {
294	      const stat = fs.lstatSync(file);
295	      if (!(stat.isFile() || stat.isSymbolicLink()) || (me !== undefined && stat.uid !== me)) continue;
296	      let ownerGone: boolean;
297	      try { process.kill(Number(match[1]), 0); ownerGone = false; } catch (err: any) { ownerGone = err?.code === "ESRCH"; }
298	      if (ownerGone) fs.unlinkSync(file);
299	    } catch { /* raced with another run */ }
300	  }
301	}
302	
303	/** Creates the entry for `op` at `at`, exclusively (never through a link), with the source's modification time. */
304	function place(sourceRoot: string, op: Exclude<Op, { kind: "dir" }>, at: string): void {
305	  if (op.kind === "symlink") {
306	    fs.symlinkSync(op.target, at);
307	    return;
308	  }
309	  fs.copyFileSync(path.join(sourceRoot, op.rel), at, fs.constants.COPYFILE_FICLONE | fs.constants.COPYFILE_EXCL);
310	  fs.utimesSync(at, op.atimeMs / 1000, op.mtimeMs / 1000);
311	}
312	
313	/**
314	 * What to copy, from Git's own ignore evaluation: `roots` are the top-level entries (files, or directories with a
315	 * trailing slash) the walk starts from and the report groups by; `only`, when set, is the exact set of files and links
316	 * selected plus the directories above them, and the walk copies nothing outside it.
317	 */
318	interface Selection { roots: string[]; only?: { files: Set<string>; dirs: Set<string> } }
319	
320	function listRoots(sourceRoot: string, all: boolean): Selection | "no-include" {
321	  const base = ["ls-files", "-z", "--others", "--ignored"];
322	  if (all) return { roots: nul(git(sourceRoot, [...base, "--directory", "--exclude-standard"]).stdout) };
323	  const file = path.join(sourceRoot, INCLUDE_FILE);
324	  const stat = fs.lstatSync(file, { throwIfNoEntry: false });
325	  if (!stat) return "no-include";
326	  if (!stat.isFile() || stat.size > 64 * 1024) throw new WorktreeError(`${INCLUDE_FILE} must be a regular file of at most 64 KiB`);
327	  // The intersection is taken file by file: a directory that the include file lists as a whole (`cache/`) is not
328	  // itself ignored when `.gitignore` only matches files inside it (`*.o`), so a collapsed entry would be dropped.
329	  const included = nul(git(sourceRoot, [...base, `--exclude-from=${file}`]).stdout);
330	  const files = new Set(included.length === 0 ? [] : nul(git(sourceRoot, ["check-ignore", "-z", "--stdin"], { input: included.join("\0") + "\0", allowFailure: true }).stdout));
331	  const dirs = new Set<string>();
332	  for (const rel of files) for (const dir of ancestors(rel)) dirs.add(dir);
333	  if (files.size === 0) return { roots: [], only: { files, dirs } };
334	  // Collapsed entries group the report; keep those that are selected or have a selected file beneath them.
335	  const collapsed = nul(git(sourceRoot, [...base, "--directory", `--exclude-from=${file}`]).stdout);
336	  return { roots: collapsed.filter((entry) => { const rel = entry.replace(/\/$/, ""); return files.has(rel) || dirs.has(rel); }), only: { files, dirs } };
337	}
338	
339	function nul(text: string): string[] {
340	  return text.split("\0").filter(Boolean);
341	}
