  const worktreePath = path.join(this.getWorktreesBaseDir(), taskId);
  const branch = `nexus/${taskId}`;

  if (!fs.existsSync(worktreePath)) {
    return {
      success: false,
      taskId,
      branch,
      commitsMerged: 0,
