  // CAND-004: Refuse merge if ignored output exists in worktree
  if (this.hasIgnoredChanges(taskId)) {
    return {
      success: false,
      taskId,
      branch,
      commitsMerged: 0,
      error: "CAND-004: Ignored worktree output exists; resolve or explicitly discard it before merging.",
