      success: true,
      taskId,
      branch,
      commitsMerged: commitCount,
    };
  } catch (err: any) {
    return {
      success: false,
      taskId,
      branch,
      commitsMerged: 0,
      error: err.stderr || err.message,
    };
  }
}

